<script setup>
import { onMounted, ref, watch } from 'vue'
import { adminApi } from '../../api/services.js'
import { useSeo } from '../../composables/useSeo.js'
import { formatDateTime,formatMoney,orderStatusLabel } from '../../utils/format.js'
const result=ref({items:[],total:0,page:1,size:25}),search=ref(''),loading=ref(false),selected=ref(null),dialogLoading=ref(false);let timer
useSeo({title:'Customers | Velmora Admin',description:'Customer history.',path:'/admin/customers',noindex:true})
async function load(){loading.value=true;try{result.value=await adminApi.customers({page:result.value.page,size:25,search:search.value||undefined})}finally{loading.value=false}}
async function open(row){dialogLoading.value=true;selected.value=null;try{selected.value=await adminApi.customer(row.phone)}finally{dialogLoading.value=false}}
function pages(){return Math.max(1,Math.ceil(result.value.total/result.value.size))}
onMounted(load);watch(search,()=>{clearTimeout(timer);timer=setTimeout(()=>{result.value.page=1;load()},300)})
</script>
<template><section class="admin-page"><div class="admin-page-head"><div><p>CUSTOMERS</p><h1 class="ui-display">Customers</h1><span>Built automatically from orders using the customer phone number.</span></div><div class="admin-counter">{{result.total}} customers</div></div><div class="admin-toolbar"><input v-model="search" class="admin-search" type="search" placeholder="Name, phone or email"></div><div class="admin-panel"><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Customer</th><th>Phone</th><th>Orders</th><th>Paid</th><th>Latest</th></tr></thead><tbody><tr v-for="c in result.items" :key="c.phone" class="admin-click-row" @click="open(c)"><td><strong>{{c.name}}</strong><small>{{c.email||'—'}}</small></td><td>{{c.phone}}</td><td>{{c.orders_count}}</td><td>{{formatMoney(c.total_spent_minor)}}</td><td>{{formatDateTime(c.last_order_at)}}</td></tr><tr v-if="!loading&&!result.items.length"><td colspan="5" class="admin-empty-cell">No customers found.</td></tr></tbody></table></div><div class="admin-pagination"><button type="button" :disabled="result.page<=1" @click="result.page--;load()">←</button><span>Page {{result.page}} / {{pages()}}</span><button type="button" :disabled="result.page>=pages()" @click="result.page++;load()">→</button></div></div><div v-if="selected||dialogLoading" class="admin-dialog-layer" @click.self="selected=null"><div class="admin-dialog admin-dialog--wide admin-panel"><div v-if="dialogLoading" class="admin-loading">Loading…</div><template v-else><div class="admin-panel-head"><div><small>CUSTOMER</small><h2>{{selected.name}}</h2><p>{{selected.phone}} · {{selected.email||'email not provided'}}</p></div><button type="button" @click="selected=null">×</button></div><div class="customer-stats"><div><span>Orders</span><strong>{{selected.orders_count}}</strong></div><div><span>Paid</span><strong>{{formatMoney(selected.total_spent_minor)}}</strong></div><div><span>Latest order</span><strong>{{formatDateTime(selected.last_order_at)}}</strong></div></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Order</th><th>Status</th><th>Total</th><th>Date</th></tr></thead><tbody><tr v-for="o in selected.orders" :key="o.id"><td><RouterLink :to="`/admin/orders/${o.id}`">#{{o.order_number}}</RouterLink></td><td>{{orderStatusLabel(o.status)}}</td><td>{{formatMoney(o.total_minor,o.currency)}}</td><td>{{formatDateTime(o.created_at)}}</td></tr></tbody></table></div></template></div></div></section></template>
